  beginnerReadingPath: [{title: 'Legalism in Chinese Philosophy', author: 'Yuri Pines', year: 2026, type: 'secondary', difficulty: 'beginner', whyRead: 'Learn why fa and the retrospective Legalist label require qualification.', sourceUrl: 'https://plato.stanford.edu/archives/spr2026/entries/chinese-legalism/'}, {title: 'Han Feizi: Basic Writings, chapters 5–7', author: 'Attributed to Han Fei; translated by Burton Watson', year: 2003, type: 'primary', difficulty: 'intermediate', whyRead: 'Introduce the ruler, administrative technique, and rewards and punishments through located chapters.', sourceUrl: 'https://cup.columbia.edu/book/han-feizi/9780231129690'}],
